   391	export async function claimInvitationWithAuth(
   392	  environment: AuthEnvironment,
   393	  auth: AuthInstance,
   394	  token: string,
   395	  body: InvitationAcceptBody,
   396	  request: Request,
   397	) {
   398	  await enforceRateLimit(environment, request, "invitation-accept", 30, 60);
   399	  const database = createDb(environment.DB);
   400	  const invitation = await readInvitation(database, await sha256Base64Url(token));
   401	  if (!invitation) throw new ApiError(404);
   402	  const now = Date.now();
   403	  const suppliedEmail = body.email ? normalizeEmail(body.email) : invitation.email;
   404	  if (suppliedEmail !== invitation.email) throw new ApiError(400);
   405	  const context = await auth.$context;
   406	  if (
   407	    body.password.length < context.password.config.minPasswordLength ||
   408	    body.password.length > context.password.config.maxPasswordLength
   409	  ) {
   410	    throw new ApiError(400);
   411	  }
   412	
   413	  let current = invitation;
   414	  if (current.status === "pending") {
   415	    if (current.expires_at <= now) {
   416	      await expireInvitation(database, current, now);
   417	      throw new ApiError(404);
   418	    }
   419	    const claimed = await database
   420	      .update(invitations)
   421	      .set({ status: "claimed", claimedAt: now, updatedAt: now })
   422	      .where(
   423	        and(
   424	          eq(invitations.id, current.id),
   425	          eq(invitations.status, "pending"),
   426	          gt(invitations.expiresAt, now),
   427	        ),
   428	      )
   429	      .returning()
   430	      .get();
   431	    current = claimed
   432	      ? toInvitation(claimed)
   433	      : ((await readInvitation(database, current.token_hash)) ?? current);
   434	  }
   435	  if (current.status === "pending" || current.status === "revoked") {
   436	    throw new ApiError(409);
   437	  }
   438	  if (current.status === "expired") {
   439	    await expireInvitation(database, current, now);
   440	    throw new ApiError(409);
   441	  }
   442	  if (current.expires_at <= now) {
   443	    await expireInvitation(database, current, now);
   444	    throw new ApiError(409);
   445	  }
   446	  if (current.status === "completed") throw new ApiError(409);
   447	
   448	  const existingUser = await database
