    22	export async function ensureControlledUserIdentity(
    23	  auth: AuthInstance,
    24	  email: string,
    25	  name: string,
    26	  existingUserId?: string | null,
    27	  allowExistingCredential = false,
    28	  existingSince?: number | null,
    29	): Promise<ManagedUser> {
    30	  const context = await auth.$context;
    31	  let user = existingUserId ? await context.internalAdapter.findUserById(existingUserId) : null;
    32	
    33	  if (!user) {
    34	    const existing = await context.internalAdapter.findUserByEmail(email, {
    35	      includeAccounts: true,
    36	    });
    37	    user = existing?.user ?? null;
    38	    if (
    39	      user &&
    40	      !allowExistingCredential &&
    41	      existing?.accounts.some((account) => account.providerId === "credential")
    42	    ) {
    43	      const createdAt = new Date(user.createdAt).getTime();
    44	      if (!existingSince || createdAt < existingSince) throw new ApiError(409);
    45	    }
    46	  }
    47	  if (user && normalizeEmail(user.email) !== email) throw new ApiError(409);
    48	
    49	  if (!user) {
    50	    try {
    51	      user = await context.internalAdapter.createUser(
    52	        { email, emailVerified: false, name },
    53	        { method: "email-password" },
    54	      );
    55	    } catch {
    56	      user =
    57	        (await context.internalAdapter.findUserByEmail(email, { includeAccounts: true }))?.user ??
    58	        null;
    59	      if (!user) throw new ApiError(500);
    60	    }
    61	  }
    62	
    63	  return user as ManagedUser;
    64	}
