    70	  allowExistingCredential = false,
    71	) {
    72	  const context = await auth.$context;
    73	  const credential = await context.internalAdapter.findCredentialAccount(managedUser.id);
    74	  if (credential) {
    75	    if (allowExistingCredential) {
    76	      const passwordHash = await context.password.hash(password);
    77	      await context.internalAdapter.updatePassword(managedUser.id, passwordHash);
    78	    }
    79	    return;
    80	  }
