    82	  const passwordHash = await context.password.hash(password);
    83	  try {
    84	    await context.internalAdapter.linkAccount({
    85	      accountId: managedUser.id,
    86	      issuer: createLocalAccountIssuer("credential"),
    87	      password: passwordHash,
    88	      providerId: "credential",
    89	      userId: managedUser.id,
